.ax{--ac:${V};border:1px solid #e3e3ee;border-radius:16px;padding:18px 20px 14px;background:#fcfcfe;color:#24233a;font-variant-numeric:tabular-nums;font-family:inherit}
.ax-head{display:flex;justify-content:space-between;align-items:flex-start;gap:12px 20px;flex-wrap:wrap}
.ax-head strong{font-size:15.5px;font-weight:650}
.ax-head p{margin:4px 0 0;font-size:13px;color:#6a6884;max-width:560px}
.ax-seg{display:flex;align-items:center;gap:4px;background:#f0f0f7;border-radius:10px;padding:3px}
.ax-seg span{font-size:12px;color:#6a6884;padding:0 6px 0 4px}
.ax-seg button{all:unset;cursor:pointer;font-size:12.5px;padding:5px 10px;border-radius:8px;color:#4a4866}
.ax-seg button.on{background:#fff;color:var(--ac);font-weight:600;box-shadow:0 1px 2px rgba(30,28,80,.12)}
.ax-seg button:focus-visible{outline:2px solid var(--ac)}
.ax-stage{margin:14px 0 4px}
.ax-arcs{display:block;overflow:visible}
.ax-arcs path{transition:stroke-width .25s,stroke-opacity .25s}
.ax-row{position:relative;display:flex;flex-wrap:wrap;gap:6px;justify-content:center}
.ax-chip{all:unset;cursor:pointer;display:flex;flex-direction:column;align-items:center;gap:2px;padding:7px 9px 5px;border-radius:10px;border:1.5px solid transparent;transition:background .25s,color .25s,border-color .15s;min-width:30px}
.ax-chip:hover{border-color:rgba(79,75,196,.45)}
.ax-chip.is-q{border-color:var(--ac);box-shadow:0 0 0 3px rgba(79,75,196,.18)}
.ax-chip:focus-visible{outline:2px solid var(--ac);outline-offset:2px}
.ax-tok{font-size:17px;font-weight:550;line-height:1.2}
.ax-w{font-size:11px;opacity:.85}
.ax-hint{text-align:center;font-size:12.5px;color:#7a7894;margin:10px 0 0}
.ax-lower{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.1fr);gap:16px 26px;margin-top:14px;padding-top:14px;border-top:1px solid #ececf3}
.ax-temp-top{display:flex;align-items:baseline;gap:10px}
.ax-temp-top label{font-size:13px;font-weight:600}
.ax-temp-top b{font-size:14px;color:var(--ac)}
.ax-reset{all:unset;cursor:pointer;margin-left:auto;font-size:12px;color:#6a6884;text-decoration:underline}
.ax input[type=range]{-webkit-appearance:none;appearance:none;width:100%;height:6px;border-radius:6px;margin:12px 0 6px;background:linear-gradient(90deg,var(--ac) var(--p),#e2e2ee var(--p));outline:none}
.ax input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:18px;height:18px;border-radius:50%;background:#fff;border:2px solid var(--ac);box-shadow:0 1px 3px rgba(0,0,0,.18);cursor:pointer}
.ax input[type=range]::-moz-range-thumb{width:16px;height:16px;border-radius:50%;background:#fff;border:2px solid var(--ac);cursor:pointer}
.ax-ends{display:flex;justify-content:space-between;font-size:11.5px;color:#8a88a2}
.ax-stats{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:12px 0 10px}
.ax-stats div{background:#f3f3f9;border-radius:10px;padding:8px 10px;display:flex;flex-direction:column;gap:2px}
.ax-stats span{font-size:11.5px;color:#6a6884}
.ax-stats b{font-size:14.5px}
.ax-formula{display:inline-block;font:12.5px Menlo,Consolas,monospace;background:#efeffa;color:#3b3880;border-radius:6px;padding:4px 8px}
.ax-tnote{margin:8px 0 0;font-size:12.5px;line-height:1.5;color:#55536e}
.ax-bars-title{font-size:12.5px;color:#6a6884;margin-bottom:6px}
.ax-bar{display:grid;grid-template-columns:64px 1fr 36px;align-items:center;gap:8px;height:20px}
.ax-bl{font-size:12.5px;text-align:right;color:#4a4866;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ax-track{height:9px;background:#efeff6;border-radius:5px;overflow:hidden}
.ax-fill{display:block;height:100%;background:rgba(79,75,196,.55);border-radius:5px;transition:width .25s}
.ax-bar.is-top .ax-fill{background:var(--ac)}
.ax-bar.is-top .ax-bl{color:var(--ac);font-weight:650}
.ax-bv{font-size:12px;color:#55536e;text-align:right}
.ax-note{margin:12px 0 0;font-size:11.5px;color:#8a88a2}
@media (max-width:620px){.ax{padding:14px 12px 12px}.ax-lower{grid-template-columns:1fr}.ax-tok{font-size:15px}.ax-chip{padding:6px 7px 4px}}
