.as{--ac:${W};border:1px solid #e3e3ee;border-radius:16px;padding:18px 20px 14px;background:#fcfcfe;color:#24233a;font-variant-numeric:tabular-nums}
.as-head strong{font-size:15.5px;font-weight:650}
.as-head p{margin:4px 0 0;font-size:13px;color:#6a6884}
.as-bar{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:10px 16px;margin:14px 0 12px}
.as-tabs{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:4px}
.as-tabs button{all:unset;cursor:pointer;display:flex;align-items:center;gap:6px;font-size:12.5px;padding:5px 10px 5px 6px;border-radius:999px;color:#55536e;border:1px solid #e3e3ee;background:#fff}
.as-tabs button i{font-style:normal;display:inline-grid;place-items:center;width:18px;height:18px;border-radius:50%;background:#efeff6;font-size:11px;color:#55536e}
.as-tabs button.done i{background:#dcdbf5;color:var(--ac)}
.as-tabs button.on{border-color:var(--ac);color:var(--ac);font-weight:600;background:#f4f3fd}
.as-tabs button.on i{background:var(--ac);color:#fff}
.as-tabs button:focus-visible,.as-follow button:focus-visible,.as-foot button:focus-visible{outline:2px solid var(--ac);outline-offset:2px}
.as-follow{display:flex;align-items:center;gap:4px;font-size:12px;color:#6a6884}
.as-follow span{margin-right:4px}
.as-follow button{all:unset;cursor:pointer;padding:3px 9px;border-radius:7px;font-size:12.5px;color:#4a4866;background:#f0f0f7}
.as-follow button.on{background:var(--ac);color:#fff;font-weight:600}
.as-inputs{display:flex;flex-wrap:wrap;align-items:flex-start;gap:10px 22px;padding:10px 12px;border-radius:12px;background:#f6f6fb}
.as-cap{width:100%;font-size:11.5px;color:#8a88a2;letter-spacing:.02em}
.as-m{transition:opacity .25s}
.as-mname{font:600 12.5px Menlo,Consolas,monospace;color:var(--ac);margin:0 0 3px 2px}
.as-m table{border-collapse:separate;border-spacing:2px;font-size:12.5px}
.as-m th{font-weight:500;color:#8a88a2;font-size:11px}
.as-m th.as-row{text-align:right;padding-right:6px;font-size:12px;color:#55536e;white-space:nowrap;cursor:pointer}
.as-m th.as-col{padding:0 2px;min-width:30px}
.as-m td{min-width:30px;text-align:center;padding:3px 5px;border-radius:5px;background:#fff;border:1px solid #e6e6f0;font-family:Menlo,Consolas,monospace;font-size:12px;transition:background .2s}
.as-m tr{cursor:pointer}
.as-m tr.is-sel td{border-color:var(--ac);box-shadow:inset 0 0 0 1px var(--ac)}
.as-m tr.is-sel th.as-row{color:var(--ac);font-weight:650}
.as-off{opacity:.38}
.as-dim{opacity:.45}
.as-m td.as-sum{background:transparent;border-color:transparent;color:#2f7d5b;font-weight:600}
.as-main{min-height:132px;display:flex;align-items:center;justify-content:center;padding:14px 0 10px}
.as-flow{display:flex;align-items:center;gap:14px;flex-wrap:wrap;justify-content:center}
.as-flow .as-m:not(.as-dim) td{font-size:13.5px;min-width:44px;padding:5px 6px}
.as-op{display:flex;flex-direction:column;align-items:center;gap:2px;font:600 13px Menlo,Consolas,monospace;color:var(--ac);white-space:nowrap}
.as-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;width:100%}
.as-cards div{border:1px solid #e3e3ee;border-radius:12px;padding:10px 12px;background:#fff;display:flex;gap:10px;align-items:flex-start}
.as-cards b{font:700 18px Menlo,Consolas,monospace;color:var(--ac)}
.as-cards span{font-size:13px;line-height:1.45;color:#3d3b58}
.as-explain{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:14px 22px;padding-top:12px;border-top:1px solid #ececf3}
.as-text h4{margin:0 0 4px;font-size:14px}
.as-text p{margin:0;font-size:13px;line-height:1.55;color:#4a4866}
.as-wt{font-size:11.5px;color:#8a88a2;margin-bottom:4px}
.as-work pre{margin:0;font:12px/1.6 Menlo,Consolas,monospace;background:#f4f3fd;color:#2e2b6b;border-radius:10px;padding:8px 10px;white-space:pre-wrap;word-break:break-word}
.as-foot{display:flex;justify-content:space-between;align-items:center;margin-top:12px}
.as-foot button{all:unset;cursor:pointer;font-size:13px;padding:6px 12px;border-radius:9px;border:1px solid #e3e3ee;background:#fff;color:#4a4866}
.as-foot button:disabled{opacity:.35;cursor:default}
.as-foot .as-primary{background:var(--ac);border-color:var(--ac);color:#fff;font-weight:600}
.as-dots{display:flex;gap:6px}
.as-dots i{width:7px;height:7px;border-radius:50%;background:#dcdbea}
.as-dots i.on{background:var(--ac)}
@media (max-width:620px){.as{padding:14px 12px 12px}.as-explain{grid-template-columns:1fr}.as-cards{grid-template-columns:1fr}.as-flow .as-dim{display:none}}
